codeExample:
.gallery {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 12px;
}

.gallery div {
  background: #d7f3f1;
  min-height: 100px;
  padding: 12px;
}

.page {
  display: grid;
  grid-template-columns: 200px 1fr;
  grid-template-rows: auto 1fr;
  gap: 12px;
}

.page header { grid-column: 1 / -1; }
